<script setup lang="ts">import{onUnmounted,ref}from'vue';import{countries}from'../data/countries';import{shuffle,shareText}from'../utils';import{sound,vibrate}from'../audio';import{useI18n,locale}from'../i18n';const{t}=useI18n(),phase=ref<'intro'|'countdown'|'play'|'end'>('intro'),country=ref(countries[0]),score=ref(0),passed=ref(0),time=ref(60),count=ref(3),feedback=ref('');let timer=0,lastGesture=0,neutral=true
function next(){country.value=shuffle(countries.filter(c=>c.code!==country.value.code))[0]}
function act(ok:boolean){if(phase.value!=='play'||Date.now()-lastGesture<850)return;lastGesture=Date.now();feedback.value=ok?t.value('correct'):t.value('pass');if(ok){score.value++;sound.correct();vibrate(35)}else{passed.value++;sound.button();vibrate(20)};setTimeout(()=>{feedback.value='';next()},420)}
function orientation(e:DeviceOrientationEvent){const beta=e.beta??0;if(Math.abs(beta)<35)neutral=true;if(neutral&&beta>55){neutral=false;act(true)}else if(neutral&&beta<20){neutral=false;act(false)}}
async function start(){const D=DeviceOrientationEvent as typeof DeviceOrientationEvent&{requestPermission?:()=>Promise<string>};try{if(D.requestPermission)await D.requestPermission()}catch{};addEventListener('deviceorientation',orientation);score.value=0;passed.value=0;time.value=60;phase.value='countdown';count.value=3;const c=setInterval(()=>{count.value--;sound.tick();if(!count.value){clearInterval(c);phase.value='play';next();timer=window.setInterval(()=>{time.value--;if(time.value<=10)sound.tick();if(time.value<=0){clearInterval(timer);phase.value='end'}},1000)}},700)}
onUnmounted(()=>{clearInterval(timer);removeEventListener('deviceorientation',orientation)});async function share(){await shareText(`FLAG STREAK PARTY 📱🌍\n🔥 ${score.value} ${t.value('flags')} in 60 secondi!`)}</script>
<template><section class="screen forehead"><template v-if="phase==='intro'"><RouterLink to="/home" class="back">← {{t('back')}}</RouterLink><div class="phone">📱</div><h1>{{t('forehead')}}</h1><p>{{t('howForehead')}}</p><div class="instructions"><div>⬇️ <b>{{t('tiltDown')}}</b></div><div>⬆️ <b>{{t('tiltUp')}}</b></div></div><button class="primary" @click="start">{{t('start')}}</button></template><div v-else-if="phase==='countdown'" class="countdown">{{count||'GO!'}}</div><template v-else-if="phase==='play'"><header class="game-head"><strong>🔥 {{score}}</strong><b class="pill">⏱ {{time}}</b><strong>↗ {{passed}}</strong></header><div class="party-card"><div class="party-flag">{{country.flagAsset}}</div><h1>{{country.names[locale].toUpperCase()}}</h1><div v-if="feedback" class="feedback">{{feedback}}</div></div><div class="touch-fallback"><button @click="act(false)">⬆️ {{t('pass')}}</button><button @click="act(true)">⬇️ {{t('correct')}}</button></div></template><div v-else class="result"><div class="burst">⏰</div><h1>{{t('timeUp')}}</h1><p>{{t('guessed')}}</p><strong class="huge">{{score}} {{t('flags')}}</strong><p>{{t('passed')}}: {{passed}}</p><button class="primary" @click="start">{{t('replay')}}</button><button @click="share">↗ {{t('share')}}</button><RouterLink to="/home" class="text-btn">{{t('home')}}</RouterLink></div></section></template>
